"""Publish the verified Managed Agents welcome video with its course audit."""
from pathlib import Path
import json,html,hashlib,shutil
R=Path(__file__).resolve().parents[1];N='managed-agents-course-welcome';P=R/'presentations'/N;V=R/'videos'/N
r=json.loads((V/'validation.json').read_text(encoding='utf-8'));assert r['fullVideoAndAudioDecode']=='passed';assert hashlib.sha256((V/r['file']).read_bytes()).hexdigest()==r['sha256']
t=json.loads((V/'timeline.json').read_text(encoding='utf-8'));story=json.loads((P/'storyboard.json').read_text(encoding='utf-8'));review=json.loads((V/'course-content-review.json').read_text(encoding='utf-8'))
assert review['lectureCount']==207 and len(review['sections'])==15 and review['practicalExamples']==60 and review['platformLabs']==75
shutil.copy2(P/'.build/video/slides/slide-01.png',V/'cover.png')
assets=[]
for name in ['portal-welcome.png','home.png','lesson.png','outcome.png','notebook.png']:
 assets.append({'asset':name,'sha256':hashlib.sha256((P/'assets'/name).read_bytes()).hexdigest(),'source':'Existing Claude Managed Agents platform artwork' if name=='portal-welcome.png' else 'Real application snapshot from the existing Managed Agents platform walkthrough; displayed at native size'})
(V/'asset-provenance.json').write_text(json.dumps(assets,indent=2),encoding='utf-8')
chapters=[]
for row,s in zip(t['slides'],story):
 sec=int(row['start']);chapters.append(f'<li><button data-start="{row["start"]}" onclick="const v=document.querySelector(\'video\');v.currentTime=Number(this.dataset.start);v.play()">{sec//60}:{sec%60:02} · {html.escape(s["title"])}</button></li>')
page=(V/'index.html').read_text(encoding='utf-8').replace('poster="highlight-preview.jpg"','poster="cover.png"')
extra='<section><h2>Lesson chapters</h2><ol style="columns:2;line-height:2">'+''.join(chapters)+'</ol><p>Outline verified: 207 lectures across 15 sections, Practical Examples 1–60 and Labs 1–75. The instructor supplied the 60-concept course structure and uploaded duration of 27h 56m. The platform preview uses real application snapshots from the previous Managed Agents walkthrough; no new live provider execution is claimed.</p><p><a href="course-content-review.json">Course content review</a> · <a href="asset-provenance.json">Preview sources</a> · <a href="narration-script.txt">Narration script</a> · <a href="geometry-audit.json">Highlight geometry</a></p></section><style>button{background:none;border:0;color:#f2b48f;font:inherit;text-align:left;cursor:pointer}li{break-inside:avoid}@media(max-width:750px){ol{columns:1!important}}</style>'
if 'Lesson chapters' not in page:page=page.replace('</main>',extra+'</main>')
(V/'index.html').write_text(page,encoding='utf-8');sec=int(r['durationSeconds']);stamp=f'{sec//60}:{sec%60:02}'
catalog=R/'videos/index.html';body=catalog.read_text(encoding='utf-8');card=f'<article data-project="{N}"><span>CLAUDE MANAGED AGENTS · WELCOME AND COURSE OVERVIEW</span><a href="{N}/index.html"><img loading="lazy" src="{N}/cover.png" alt="Claude Managed Agents Welcome and Course Overview"></a><div><h2>Claude Managed Agents: Welcome and Course Overview</h2><p>Verified · {stamp} · 1080p · 207 lectures · 60 concepts + 60 examples · 75 labs</p><a href="{N}/{r["file"]}">MP4</a> · <a href="{N}/index.html">Player and chapters</a></div></article>'
if f'data-project="{N}"' not in body:catalog.write_text(body.replace('<main>','<main>'+card,1),encoding='utf-8')
(V/'README.txt').write_text(f'CLAUDE MANAGED AGENTS: WELCOME AND COURSE OVERVIEW\nUdemy lesson title: Welcome & Course Overview\nDuration: {stamp}. 1920x1080, 30 fps, H.264/AAC. Inworld Yash, TTS 2, enhanced, balanced delivery, speaking rate 1.25, 48kHz.\n\n14 scenes: course cover; scale; Sections 1-4; Sections 5-8; Sections 9-13; platform and optional foundation; provider/host boundary; concept/example/lab/evidence cycle; platform home; first-lab workspace; offline outcomes; learning notebook and progress; study path; next lecture.\n\nThe attached outline contains continuous lectures 1-207, 15 sections, Practical Examples 1-60 and Labs 1-75. Core 60-concept structure and 27h56m upload total are supplied by the instructor. No SDK-course topics, milestone project claims or SDK platform pictures are reused as Managed Agents content. Shared production styling and tooling are reused. Managed Agents platform screenshots and artwork come from its existing walkthrough.\n\nText bounds, fitted highlights, word timestamps, full decode, audio synchronization, phrase boundaries, stale-outline removal and chapter navigation are checked. No new provider run or deployment is claimed.\n\nRebuild: python scripts/create-managed-agents-course-welcome.py; node scripts/capture-managed-agents-course-welcome.mjs; python scripts/create-managed-agents-course-welcome.py; python scripts/audit-managed-agents-course-welcome.py; python -u scripts/build-narrated-presentation.py --project {N}; python scripts/finish-managed-agents-course-welcome.py\n',encoding='utf-8')
print(f'Managed Agents welcome player ready: {stamp}, {len(chapters)} chapters.')
